/* Enjambre: un zunzun defiende su jardin de insectos. Juego original de disparos */
#include "z.h"
#define GW 720
#define GH 520
#define NI 36
typedef struct { float x, y; int ty, hp, on; } ins_t; typedef struct { float x, y, vy; int on; } sh_t; typedef struct { float x, y, vx, vy; int life; u32 c; } pt_t;
typedef struct { double ph, f, df, a, dc; int noise; } vo_t;
static zwin *W; static ins_t I[NI]; static sh_t P[4], E[14]; static pt_t X[80]; static vo_t V[10]; static int flw[3], score, best, lives, level, over, pause_, keyL, keyR, keyF, cool, frame, inv, nalive; static float px, sway, drop; static float qx = -200; static int qdir, qhp; static u32 rs_ = 12345;
static u32 R(void) { rs_ = rs_ * 1103515245 + 12345; return rs_ >> 8; }
static void snd(double f, double df, double a, double dc, int nz) { for (int i = 0; i < 10; i++) if (V[i].a < 0.001) { V[i] = (vo_t){0, f, df, a, dc, nz}; return; } }
static void audio(void) { static short b[1600]; if (524288 - z_audio_space() > 9600) return; static u32 nr = 77; for (int i = 0; i < 800; i++) { double s = 0; for (int k = 0; k < 10; k++) { vo_t *v = &V[k]; if (v->a < 0.001) continue; v->ph += v->f / 48000; if (v->ph >= 1) v->ph -= 1; v->f += v->df; if (v->f < 30) v->f = 30; double o; if (v->noise) { nr = nr * 1664525 + 1013904223; o = ((nr >> 16) & 255) / 127.5 - 1; } else o = v->ph < 0.5 ? 4 * v->ph - 1 : 3 - 4 * v->ph; s += o * v->a; v->a *= v->dc; } int q = s * 9000; q = MAX(-30000, MIN(q, 30000)); b[i * 2] = q; b[i * 2 + 1] = q; } z_audio(b, 3200); }
static void boom(float x, float y, u32 c, int n) { for (int i = 0, k = 0; i < 80 && k < n; i++) if (X[i].life <= 0) { X[i] = (pt_t){x, y, (int)(R() % 41 - 20) / 8.0f, (int)(R() % 41 - 24) / 8.0f, 18 + R() % 16, c}; k++; } }
static void wave(void) { memset(E, 0, sizeof E); memset(P, 0, sizeof P); sway = 0; drop = 0; int k = 0; static const int rows[5] = {5, 8, 9, 8, 6}; for (int r = 0; r < 5; r++) for (int c = 0; c < rows[r] && k < NI; c++, k++) I[k] = (ins_t){GW / 2 + (c - (rows[r] - 1) / 2.0f) * 62, 58 + r * 40, r < 1 ? 2 : r < 3 ? 1 : 0, r < 1 ? 2 : 1, 1}; nalive = k; snd(392, 1.2 * 0.01, .35, .9998, 0); }
static void reset(void) { score = 0; lives = 3; level = 1; over = 0; px = GW / 2; for (int i = 0; i < 3; i++) flw[i] = 255; qx = -200; wave(); }
static void bug(int x, int y, int ty, int f) { static const u32 B[] = {0xF5B700, 0xD9303E, 0x7A3FC4}, D[] = {0x2B2118, 0x3A1014, 0x24113F}; int w = f & 8 ? 13 : 8; g_circle(W, x - 9, y - 4 - (f & 8 ? 3 : 0), w / 2 + 3, 0xE8F7FF, 1); g_circle(W, x + 9, y - 4 - (f & 8 ? 3 : 0), w / 2 + 3, 0xE8F7FF, 1); g_circle(W, x, y, 11, B[ty], 1); g_circle(W, x, y - 11, 6, D[ty], 1); if (ty == 0) { g_rect(W, x - 10, y - 2, 21, 3, D[0]); g_rect(W, x - 8, y + 5, 17, 3, D[0]); } else if (ty == 1) { g_rect(W, x, y - 10, 1, 21, D[1]); g_circle(W, x - 5, y, 2, D[1], 1); g_circle(W, x + 5, y + 3, 2, D[1], 1); } else { g_circle(W, x, y, 5, 0xF0ABFC, 1); g_circle(W, x, y, 2, D[2], 1); } g_line(W, x - 3, y - 16, x - 7, y - 21, D[ty]); g_line(W, x + 3, y - 16, x + 7, y - 21, D[ty]); }
static void flower(int cx, int cy, int m) { g_rect(W, cx - 2, cy, 4, GH - 34 - cy, 0x2E8B57); for (int i = 0; i < 8; i++) if (m & 1 << i) { static const signed char dx[] = {0, 15, 21, 15, 0, -15, -21, -15}, dy[] = {-21, -15, 0, 15, 21, 15, 0, -15}; g_circle(W, cx + dx[i], cy + dy[i], 10, i & 1 ? 0xFF8FB8 : 0xFF6FA5, 1); } if (m) g_circle(W, cx, cy, 9, 0xFFD23F, 1); }
static void hero(int x, int y, int f) { int fl = f & 4 ? 8 : 0; g_line(W, x - 3, y + 4, x - 28, y - 3 - fl, 0x9FE8DC); g_line(W, x - 3, y + 7, x - 26, y + 4 - fl, 0x56C7B6); g_line(W, x + 3, y + 4, x + 28, y - 3 - fl, 0x9FE8DC); g_line(W, x + 3, y + 7, x + 26, y + 4 - fl, 0x56C7B6); g_circle(W, x, y + 6, 9, 0x0FA08C, 1); g_circle(W, x, y - 6, 7, 0xE5395A, 1); g_circle(W, x + 2, y - 8, 1, 0, 1); g_rect(W, x, y - 25, 1, 13, 0x222222); g_rect(W, x - 4, y + 14, 8, 6, 0x0B7567); }
static void draw(void) { g_grad(W, 0, 0, GW, GH - 90, 0x9FDcF6 & 0xFFFFFF, 0xFFF1CF); g_circle(W, 620, 70, 34, 0xFFE27A, 1); for (int i = 0; i < 4; i++) { int x = 70 + i * 190; g_circle(W, x, 120 + (i & 1) * 30, 16, 0xFFFFFF, 1); g_circle(W, x + 18, 116 + (i & 1) * 30, 21, 0xFFFFFF, 1); g_circle(W, x + 40, 122 + (i & 1) * 30, 14, 0xFFFFFF, 1); } for (int x = 0; x < GW; x += 2) { int h = 34 + (int)(14 * z_sin(x / 70.0)); g_rect(W, x, GH - 90 - h, 2, h, 0x8BCB74); } g_rect(W, 0, GH - 90, GW, 90, 0x5DAA52); for (int x = 6; x < GW; x += 13) g_line(W, x, GH - 34, x + (x & 8 ? 4 : -4), GH - 44, 0x3F8A3B); for (int i = 0; i < 3; i++) flower(150 + i * 210, GH - 150, flw[i]); for (int i = 0; i < NI; i++) if (I[i].on) bug(I[i].x + 18 * z_sin(sway + I[i].y / 50), I[i].y + drop, I[i].ty, frame + i * 3); if (qx > -100) { int x = qx, y = 30; g_circle(W, x - 16, y, 12, 0xF7D154, 1); g_circle(W, x + 4, y, 15, 0xE28E12, 1); g_circle(W, x + 22, y, 9, 0x2B2118, 1); g_rect(W, x - 3, y - 14, 3, 28, 0x2B2118); g_rect(W, x + 8, y - 13, 3, 26, 0x2B2118); } for (int i = 0; i < 4; i++) if (P[i].on) { g_circle(W, P[i].x, P[i].y, 4, 0xFFF06A, 1); g_circle(W, P[i].x, P[i].y, 2, 0xFF9F1C, 1); } for (int i = 0; i < 14; i++) if (E[i].on) { g_line(W, E[i].x, E[i].y - 8, E[i].x, E[i].y + 6, 0x4A2C14); g_rect(W, E[i].x - 1, E[i].y + 5, 3, 3, 0xD9303E); } for (int i = 0; i < 80; i++) if (X[i].life > 0) g_rect(W, X[i].x, X[i].y, 3, 3, X[i].c); if (!over && !(inv & 4)) hero(px, GH - 56, frame); g_rect(W, 0, GH - 28, GW, 28, 0x234D2A); char b[80]; snprintf(b, 80, _("Polen %06d    Mejor %06d    Jardin %d"), score, best, level); g_text(W, 12, GH - 22, b, 0xF3FFE9); for (int i = 0; i < lives; i++) g_circle(W, GW - 22 - i * 22, GH - 14, 6, 0xE5395A, 1); if (over || pause_) { const char *t = over ? "El jardin ha caido" : "Pausa", *u = over ? "Intro para volver a volar" : "P para seguir"; g_round(W, GW / 2 - 200, GH / 2 - 62, 400, 110, 10, 0x234D2A); g_text2(W, (GW - g_textw(t) * 2) / 2, GH / 2 - 44, t, 0xFFF06A, 2); g_text(W, (GW - g_textw(u)) / 2, GH / 2 + 2, u, 0xFFFFFF); } zw_present(W); }
static void hit_me(void) { if (inv) return; lives--; boom(px, GH - 56, 0xE5395A, 26); snd(180, -.004, .7, .99995, 1); inv = 110; if (lives <= 0) { over = 1; if (score > best) best = score; char m[50]; snprintf(m, 50, "[prueba] enjambre fin: %d", score); z_log(m); } }
static int flower_hit(float x, float y) { for (int i = 0; i < 3; i++) { int cx = 150 + i * 210, cy = GH - 150; float dx = x - cx, dy = y - cy; if (dx * dx + dy * dy < 34 * 34 && flw[i]) { static const signed char ax[] = {0, 15, 21, 15, 0, -15, -21, -15}, ay[] = {-21, -15, 0, 15, 21, 15, 0, -15}; for (int p = 0; p < 8; p++) if (flw[i] & 1 << p) { float a = x - cx - ax[p], b = y - cy - ay[p]; if (a * a + b * b < 15 * 15) { flw[i] &= ~(1 << p); boom(x, y, 0xFF8FB8, 6); return 1; } } } } return 0; }
static void step(void) { frame++; if (inv) inv--; px += (keyR - keyL) * 5.2f; px = MAX(30.f, MIN(px, (float)GW - 30)); if (cool) cool--; if (keyF && !cool) for (int i = 0; i < 4; i++) if (!P[i].on) { P[i] = (sh_t){px, GH - 82, -9, 1}; cool = 14; snd(980, -.05, .28, .9994, 0); break; } sway += .018f + .004f * level + (NI - nalive) * .0009f; drop += .018f + .007f * level; for (int i = 0; i < 4; i++) if (P[i].on) { P[i].y += P[i].vy; if (P[i].y < -10) P[i].on = 0; else if (flower_hit(P[i].x, P[i].y)) P[i].on = 0; for (int k = 0; k < NI && P[i].on; k++) if (I[k].on) { float x = I[k].x + 18 * z_sin(sway + I[k].y / 50), y = I[k].y + drop, dx = x - P[i].x, dy = y - P[i].y; if (dx * dx + dy * dy < 15 * 15) { P[i].on = 0; if (--I[k].hp <= 0) { I[k].on = 0; nalive--; score += 10 * (I[k].ty + 1) * level; boom(x, y, I[k].ty == 0 ? 0xF5B700 : I[k].ty == 1 ? 0xD9303E : 0x7A3FC4, 14); snd(240 + I[k].ty * 90, -.01, .4, .9995, 1); } else snd(620, 0, .2, .998, 0); } } if (P[i].on && qx > -100) { float dx = qx - P[i].x, dy = 30 - P[i].y; if (dx * dx + dy * dy < 26 * 26) { P[i].on = 0; if (--qhp <= 0) { score += 500 * level; boom(qx, 30, 0xE28E12, 40); qx = -200; for (int f = 0; f < 3; f++) flw[f] = 255; snd(523, .02, .5, .99993, 0); } } } } if (R() % MAX(10, 36 - level * 3) == 0 && nalive) { int k = R() % NI; for (int t = 0; t < NI && !I[k].on; t++) k = (k + 1) % NI; for (int i = 0; i < 14; i++) if (!E[i].on) { E[i] = (sh_t){I[k].x + 18 * z_sin(sway + I[k].y / 50), I[k].y + drop + 12, 2.8f + level * .25f, 1}; snd(210, -.006, .12, .9993, 0); break; } } for (int i = 0; i < 14; i++) if (E[i].on) { E[i].y += E[i].vy; if (E[i].y > GH - 34) E[i].on = 0; else if (flower_hit(E[i].x, E[i].y)) E[i].on = 0; else { float dx = E[i].x - px, dy = E[i].y - (GH - 56); if (dx * dx + dy * dy < 17 * 17 && !inv) { E[i].on = 0; hit_me(); } } } for (int k = 0; k < NI; k++) if (I[k].on) { float y = I[k].y + drop; if (y > GH - 80) { over = 1; if (score > best) best = score; } } if (qx <= -100 && R() % 900 == 0) { qdir = R() & 1 ? 1 : -1; qx = qdir > 0 ? -60 : GW + 60; qhp = 3; } if (qx > -100) { qx += qdir * 2.4f; if (frame % 12 == 0) snd(150, .1, .1, .9992, 0); if (qx < -80 || qx > GW + 80) qx = -200; } for (int i = 0; i < 80; i++) if (X[i].life > 0) { X[i].x += X[i].vx; X[i].y += X[i].vy; X[i].vy += .12f; X[i].life--; } if (!nalive) { level++; score += 100 * level; static const int nt[] = {523, 659, 784}; for (int i = 0; i < 3; i++) snd(nt[i], 0, .3, .9998, 0); wave(); } }
int main(const char *a) { W = zw_new("Enjambre", -1, 0, GW, GH, WF_DECOR); reset(); zevent e; u64 next = z_ms(); z_log("[prueba] enjambre iniciado"); for (;;) { long w = (long)next - (long)z_ms(); if (w < 1) w = 1; if (z_event(&e, w)) { if (e.type == EV_CLOSE) return 0; if (e.type == EV_REDRAW) draw(); if (e.type == EV_KEY || e.type == EV_KEYUP) { int d = e.type == EV_KEY; if (e.key == K_LEFT) keyL = d; else if (e.key == K_RIGHT) keyR = d; else if (e.key == 0x2C) keyF = d; else if (d && (e.ch == 'p' || e.ch == 'P')) pause_ = !pause_; else if (d && e.ch == '\n' && over) reset(); } continue; } next = z_ms() + 16; if (!over && !pause_) step(); audio(); draw(); } }
